// field and role → packs, in the order they fill the box. The field decides; for "Other" or a field typed by hand,
// the words in the field and role decide (a nurse who typed "Nursing" still gets nursing).
const PACK_RULES = [
    [/technolog|software|^it$|computer|engineering|developer|data scien|devops|programm/, null],
    [/human res|\bhr\b|hrbp|recruit|talent|people (ops|operations|partner|and culture|& culture)|payroll|learning (and|&) development|l&d/, ['hr', 'business', 'craft']],
    [/health|nurs|medic|clinic|hospital(?!ity)|pharm|doctor|mbbs|dental|physio/, 'health'],
    [/business|mba|management|consult|strateg|product manag|entrepreneur/, ['business', 'marketing', 'finance', 'craft']],
    [/financ|account|bank|audit|tax|\bca\b|invest/, ['finance', 'business', 'craft']],
    [/sales|business develop|\bbd\b|account exec/, ['sales', 'business', 'craft']],
    [/seo|search engine/, ['seo', 'marketing', 'craft']],
    [/market|brand|advertis|social media|content|digital|growth|\bpr\b|communication/, 'marketing'],
    [/design|ux|ui\b|graphic|illustrat|architect/, ['design', 'craft']],
    [/educat|teach|tutor|lectur|professor|school|b\.?ed/, ['education', 'craft']],
    [/operation|supply|logistic|procure|warehouse|manufactur/, ['ops', 'business', 'craft']],
    [/law|legal|llb|advocate|lawyer|paralegal|compliance/, ['law', 'craft']],
    [/hospitality|hotel|restaurant|chef|culinary|travel|tourism|aviation|cabin crew|airline/, ['hospitality', 'craft']],
    [/government|public|civil serv|upsc|policy|ngo|social work/, ['public', 'craft']],
];
function bentoPacksFor(field = '', role = '') {
    const f = String(field).trim().toLowerCase(), r = String(role).trim().toLowerCase();
    if (!f && !r) return null;   // not onboarded yet: the original tech tracks
    const pick = hit => {
        if (hit !== 'health' && hit !== 'marketing') return hit;
        if (hit === 'marketing') return /seo|search|content|digital|growth/.test(r) ? ['seo', 'marketing', 'craft'] : ['marketing', 'seo', 'craft'];
        if (/nurs|gnm|anm|\bicu\b|ward|midwi/.test(`${f} ${r}`)) return ['nursing', 'craft'];
        if (/doctor|mbbs|physician|resident|medical officer|surgeon|\bmd\b|clinician|medicine/.test(`${f} ${r}`)) return ['medicine', 'craft'];
        return ['nursing', 'medicine', 'craft'];
    };
    const listed = f && f !== 'other';
    for (const text of listed ? [f] : [f, r].filter(Boolean)) for (const [re, packs] of PACK_RULES) if (re.test(text)) return pick(packs);
    return ['craft', 'business'];   // interview craft for everyone, plus the basics of how organisations work
}

